type Asset = { id:number; kind:string; filename:string|null; source_url:string; storage_path:string|null; mime_type:string|null; extracted_text:string|null; extra?:any };
type Account = { student_id:string; name:string|null; major:string|null; year:number|null; has_timetable:boolean; has_grade_distribution:boolean; has_cumulative_grades:boolean; has_graduation_credits:boolean; lms_course_count:number; lms_task_count:number; llm_accounts?:{id:string;provider:string;label:string;model:string;active:boolean}[] };
