function attachmentSubsteps(att:any,resumeWaiting=false){const steps=Array.isArray(att.substeps)?att.substeps:[];if(!steps.length)return '';const label=(step:any)=>{let status=step.status==='complete'?'완료':step.status==='processing'?'진행 중':step.status==='failed'?'실패':'시작 전';if(resumeWaiting&&step.status==='processing')status='중단';const count=Number.isFinite(Number(step.total))&&Number(step.total)>0?` · ${Number(step.completed||0)} / ${Number(step.total)}`:'';const cssState=resumeWaiting&&step.status==='processing'?'waiting':step.status||'pending';return `<li class="${h(cssState)}"><i></i><span>${h(step.label||step.key)}</span><small>${h(status)}${h(count)}${step.current?` · ${h(step.current)}`:''}</small></li>`};return `<ol class="attachment-substeps">${steps.map(label).join('')}</ol>`;}
