const documentInternalKinds=new Set(["attachment_hwp_structure","attachment_hwp_markdown","attachment_hwp_validation","attachment_hwp_image","attachment_hwp_binary","attachment_document_image","inline_image"]);
function attachmentMarkup(asset:Asset){return `<details><summary>${h(asset.filename||asset.kind)}</summary><pre>${h(asset.extracted_text||'추출 텍스트 없음')}</pre>${asset.source_url?`<button class="text-link" data-external-url="${h(asset.source_url)}">첨부 원본 열기</button>`:''}</details>`;}
function qualityMarkup(asset:Asset|undefined){if(!asset)return '<p class="muted">구조·품질 정보 없음</p>';try{const value=JSON.parse(asset.extracted_text||'{}');return `<dl class="quality-grid"><dt>판정</dt><dd>${h(value.status||'없음')}</dd><dt>품질 점수</dt><dd>${value.score==null?'없음':h(Math.round(Number(value.score)*1000)/10+'%')}</dd><dt>본문 일치도</dt><dd>${value.textTokenF1==null?'없음':h(Math.round(Number(value.textTokenF1)*1000)/10+'%')}</dd><dt>표</dt><dd>${h(value.tableCount??0)}개 · 셀 ${h(value.tableCellCount??0)}개</dd></dl>`;}catch{return `<pre>${h(asset.extracted_text||'품질 정보 없음')}</pre>`;}}
function documentAnalysisMarkup(assets:Asset[]){if(!assets.length)return '';const structure=assets.find(a=>a.kind==="attachment_hwp_structure");const markdown=assets.some(a=>a.kind==="attachment_hwp_markdown");const validation=assets.some(a=>a.kind==="attachment_hwp_validation");const images=assets.filter(a=>a.kind==="attachment_hwp_image"||a.kind==="attachment_document_image"||a.kind==="inline_image").sort((a,b)=>Number(a.extra?.figure?.number??999)-Number(b.extra?.figure?.number??999));const binaries=assets.filter(a=>a.kind==="attachment_hwp_binary");return `<details class="processing-results"><summary>본문·문서 그림 처리 상세 · 내부 파일 ${assets.length}개</summary><p class="muted">공지 본문과 HWP·HWPX·PDF·Word·Excel·PowerPoint의 검증된 그림 설명만 번호와 문맥을 포함해 검색에 사용합니다.</p>${structure?qualityMarkup(structure):''}${structure?`<div class="process-flags"><span>${markdown?'✓':'—'} 검색용 Markdown</span><span>${validation?'✓':'—'} HWPX 교차 검증</span></div>`:''}${images.length?`<h4>본문·문서 그림 ${images.length}개</h4><div class="asset-images">${images.map(a=>{const figure=a.extra?.figure;const analysis=a.extra?.analysis;const label=figure?.label||a.filename||'문서 내부 이미지';return `<figure><div class="asset-preview"><span>미리보기 불러오는 중…</span><img data-asset-preview="${a.id}" alt="${h(label)}"/></div><figcaption><strong>${h(label)} · ${h(a.filename)}</strong><span>${h(analysis?.description||'이미지 설명은 아직 생성되지 않았습니다.')}</span>${figure?.context?`<details class="image-context"><summary>문서 내 위치</summary><span>${h(figure.context)}</span></details>`:''}</figcaption></figure>`}).join('')}</div>`:''}${binaries.length?`<p class="muted">기타 내부 바이너리 ${binaries.length}개</p>`:''}</details>`;}
async function loadAssetPreviews(){await Promise.all([...document.querySelectorAll<HTMLImageElement>("[data-asset-preview]")].map(async img=>{const preview=img.parentElement;const message=preview?.querySelector<HTMLElement>("span");const fail=()=>{img.alt="이미지 미리보기를 불러오지 못했습니다.";if(message)message.textContent="미리보기를 불러오지 못했습니다.";preview?.classList.remove("loaded");preview?.classList.add("failed")};try{const result=await api(`/assets/${encodeURIComponent(img.dataset.assetPreview||'')}/preview`);img.onload=()=>{preview?.classList.remove("failed");preview?.classList.add("loaded")};img.onerror=fail;img.src=result.data_url;if(img.complete){if(img.naturalWidth)preview?.classList.add("loaded");else fail()}}catch{fail()}}));}
